// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    X_WALLET c;
    function setUp() public { c = new X_WALLET(address(new Log())); }

    function testFuzz_property(uint256 unlockTime, uint256 warpDelta, address actor, uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        unlockTime = bound(unlockTime, 0, type(uint256).max / 2);
        warpDelta = bound(warpDelta, 0, type(uint256).max / 4);
        amount = bound(amount, 0, address(this).balance);
        vm.warp(block.timestamp + warpDelta);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);
        assertTrue(__invmut_c_Acc_unlockTime(actor) >= block.timestamp);
    }

    function __invmut_c_Acc_unlockTime(address __k) internal view returns (uint256) {
        (uint256 _v0, ) = c.Acc(__k);
        return _v0;
    }
}
